window.MONSTER_CHUNK_57 = [{"name":"Mythic Lamia","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"monstrous humanoid","subtypes":["mythic","shapechanger"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["seduction (DC 16)"],"ac":24,"ac_touch":14,"ac_flat_footed":19,"ac_mods":"+3 Dex, +2 dodge, +10 natural, -1 size","hp":97,"hd":"9d10+48","hdvalue":9,"fort":7,"ref":9,"will":11,"dr":"5/epic","speed":[{"type":"land","speed":60}],"melee":"+1 scimitar +13 (1d6+5/18-20), 2 claws +12 (1d4+2), touch +7 (1d4 Wisdom drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"mythic power","details":"3/day, surge +1d6"},{"type":"pounce"},{"type":"Wisdom drain"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"disguise self"},{"spell":"ventriloquism"}]},{"frequency":"1/day","spells":[{"spell":"deep slumber"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"major image"},{"spell":"mirror image"},{"spell":"suggestion"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":6,"spellsknown_concentration":8,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"haste"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"death knell"},{"spell":"invisibility"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"mage armor"},{"spell":"magic missile"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"strength":18,"dexterity":16,"constitution":14,"intelligence":13,"wisdom":17,"charisma":15,"baseatk":9,"cmb":14,"cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge","type":"mythic"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Spring Attack","type":"mythic"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Diplomacy","value":5},{"skill":"Disguise","value":7},{"skill":"Intimidate","value":11},{"skill":"Knowledge (religion)","value":4},{"skill":"Perception","value":15},{"skill":"Stealth","value":15},{"skill":"Survival","value":12}],"languages":["Abyssal","Common"],"sq":[{"type":"change shape","details":"giant constrictor snake, lamia matriarch, or lion; polymorph"},{"type":"undersized weapons"}],"environments":["temperate deserts"],"organizations":["solitary","pair","cult (3-12)"],"treasure":"double (+1 scimitar)","description_visual":"This creature has the head and upper body of a beautiful woman, the lower body of a lion, and long, serpentine tail.","group":"Lamia","source":"Mythic Adventures","special_abilities":[{"type":"Aura of Seduction","kind":"Su","details":"Any creature within 30 ft. of a mythic lamia must succeed at a DC 16 Will save or become fascinated. A creature that succeeds at this save is immune to the lamia's aura for 24 hours. This is a mind-affecting effect. The save DC is Charisma-based. Spells A mythic lamia casts spells as a 6th-level sorcerer, and can cast spells from the cleric list as well as those normally available to a sorcerer. Cleric spells are considered arcane spells for a mythic lamia."},{"type":"Wisdom Drain","kind":"Su","details":"A lamia drains 1d4 points of Wisdom each time she hits with her melee touch attack. (Unlike with other kinds of ability drain attacks, a lamia doesn't heal any damage when she uses her Wisdom drain.) Lamias try to use this power early in an encounter to make foes more susceptible to charm monster and suggestion."}],"description":"A mythic lamia dabbled in dark pacts or strange magic in an attempt to break the ancient curse that gives her a monstrous form, but instead gained the ability to change her shape as well as other magical abilities. Impressed by her progress but angered by her lack of complete success, she continues her research and plotting.\n\nLamia Matriarch\n\nIn most cases, a mythic lamia will permanently transform into a lamia matriarch, losing her mythic power as she stabilizes in that form. A lamia matriarch that gains mythic power gains the mythic lamia's aura of seduction, a tail slap attack, grab, and constrict. She increases her sorcerer caster level to 8th and usually learns spells that aid her minions, such as freedom of movement and rage. She may use her touch attack to drain Wisdom or drain one use of mythic power from the target and regain one of her own uses of mythic power (save negates).","ecology":"","habitat_society":""},{"name":"Mythic Mummy","cr":7,"xp":3200,"alignment":"LE","size":"Medium","type":"undead","subtypes":["mythic"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["despair (30 ft., paralyzed for 1d4 rounds, Will DC 16 negates)"],"ac":23,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+13 natural","hp":92,"hd":"8d8+56","hdvalue":8,"hp_mods":["fast healing 5"],"fort":4,"ref":2,"will":8,"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20}],"melee":"slam +15 (1d8+12 plus mummy rot)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"mythic power","details":"3/day, surge +1d6"}],"strength":26,"dexterity":10,"intelligence":6,"wisdom":15,"charisma":15,"baseatk":6,"cmb":14,"cmd":24,"feats":[{"feat":"Power Attack","type":"mythic"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness","type":"mythic"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":16},{"skill":"Stealth","value":11}],"languages":["Common"],"sq":[{"type":"change shape","details":"any humanoid; alter self"},{"type":"desert mastery"}],"environments":["any"],"organizations":["solitary","warden squad (2-6)","guardian detail (7-12)"],"treasure":"standard","description_visual":"This regal mummy reeks of preservative spices and wears the clothing and jewelry of a wealthy pharaoh.","group":"Mummy","source":"Mythic Adventures","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"As a swift action, a mythic mummy can expend one use of mythic power to transform a slain opponent into a non-mythic mummy with the advanced simple template. The new mummy is under the command of the mummy that created it, and remains enslaved until the mythic mummy's death, at which time it becomes a free-willed creature. The spawn retains none of the abilities it had in life."},{"type":"Desert Mastery","kind":"Su","details":"A mythic mummy can command earth and sand within 100 ft. to c reate a variety of spell-like effects. As a s tandard action, a mummy can reduce rock to sand (as transmute rock to mud) or create lifelike shapes made from sand (as major image, though these shapes collapse if disbelieved or attacked). The mummy can expend one use of mythic power to summon a giant advanced sandman. The mummy's caster level equals its Hit Dice for these effects."},{"type":"Despair","kind":"Su","details":"All creatures within a 30-foot radius that see a mummy must succeed at a DC 18 Will save or be paralyzed by fear for 1d4 rounds. A creature only has to attempt this save against a particular mummy's despair ability once every 24 hours. This is a paralysis and mind-affecting fear effect. The save DC is Charisma-based and includes a +2 racial bonus."},{"type":"Mummy Rot","kind":"Su","details":"Curse and disease-slam; save Fort DC 18; onset 1 minute; frequency 1/day; effect 1d6 Con and 1d6 Cha; cure -. This otherwise functions like standard mummy rot. The DC is Charisma-based and includes a +2 racial bonus."}],"description":"A mythic mummy is the preserved and animated remains or royalty-the honored dead a common mummy is compelled to protect. Wielding powers over sand and able to create new minions to replace the fallen, a mythic mummy is a formidable opponent. Its used to absolute obedience from living and undead subjects. If awakened from its eternal rest, a mythic mummy uses its magic to appear as it did in life, though if angered or surprised it may reveal its undead form.","ecology":"","habitat_society":""},{"name":"Naunet","cr":7,"xp":3200,"alignment":"CN","size":"Large","type":"outsider","subtypes":["chaotic","extraplanar","protean","shapechanger"],"init":7,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"detect law"}],"ac":20,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+3 Dex, +8 natural, -1 size","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":11,"will":6,"defensive_abilities":["amorphous anatomy","freedom of movement"],"dr":"5/lawful","immunities":["acid","polymorph"],"resists":[{"type":"electricity","value":10},{"type":"sonic","value":10}],"sr":18,"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"perfect"},{"type":"swim","speed":30}],"melee":"bite +14 (1d8+5) , tail slap +11 (1d6+2 plus grab), 2 tentacles +11 (1d6+2 plus confusion)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"adaptive strike"},{"type":"coalesce chaos"},{"type":"constrict","details":"1d6+5"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect law"}]},{"frequency":"at-will","spells":[{"spell":"acid arrow"},{"spell":"dimension door","details":"self plus 50 lbs. of objects only"},{"spell":"fog cloud"},{"spell":"shatter"}]},{"frequency":"1/day","spells":[{"spell":"chaos hammer"}]}],"strength":20,"dexterity":17,"constitution":20,"intelligence":11,"wisdom":16,"charisma":15,"baseatk":9,"cmb":15,"cmd":28,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Fly","value":9},{"skill":"Intimidate","value":14},{"skill":"Perception","value":15},{"skill":"Stealth","value":11},{"skill":"Survival","value":15},{"skill":"Swim","value":25}],"languages":["Abyssal","Protean"],"sq":[{"type":"change shape","details":"polymorph"}],"environments":["any (Limbo)"],"organizations":["solitary","pair","cacophony (3-12)"],"treasure":"none","description_visual":"Tentacles tipped with snapping jaws emerge from this serpentine creature's back, complementing the vicious maw in its reptilian face.","group":"Protean","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Adaptive Strike","kind":"Su","details":"A naunet's natural weapons count as magical and chaotic for the purposes of overcoming damage reduction. As a free action once per round, a naunet may infuse all of its natural attacks with adamantine, silver, or cold iron, thereby allowing it to overcome damage reduction of those types as well."},{"type":"Coalesce Chaos","kind":"Su","details":"Once per day as a standard action, three or more naunets working together can create a roiling cloud of multicolored chaos matter. This effect is identical to solid fog (CL 12th) and lasts for 2d6 rounds. If six or more naunets are present, the coalesced chaos instead functions as acid fog (CL 12th)."},{"type":"Confusion","kind":"Su","details":"A creature struck by a naunet's tentacle attack is infused with raw chaos, and must make a DC 19 Will save or be confused for 1 round. Rounds of confusion dealt in this manner stack. A creature with a chaotic component to its alignment gains a +4 bonus on saves against this effect, and creatures with the chaotic subtype are immune. This is a mind-affecting effect. The save DC is Constitution-based."}],"description":"Far more bestial than their kin, naunets are the lowest caste of the true proteans, the shock troops of their race and roving marauders in the cause of chaos. Primarily found in the shifting borderlands between Limbo and other planes, naunets are driven half-insane by the stability and stasis of such areas, and frequently rampage through the edges of other planes, tearing up the very fabric of reality itself and returning vast swaths of land to the beautiful, formless potentiality of their home.\n\nA naunet is 12 ft. long and weighs 900 pounds.","ecology":"","habitat_society":""},{"name":"Ngoga","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"magical beast","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["stench (DC 18, 10 rounds)"],"ac":20,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+5 Dex, +6 natural, -1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":10,"ref":11,"will":6,"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"speed_mod":"burst of speed","melee":"bite +14 (1d8+6), 2 claws +14 (1d6+6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d6+9"}],"strength":23,"dexterity":20,"constitution":18,"intelligence":2,"wisdom":13,"charisma":9,"baseatk":9,"cmb":16,"cmd":31,"feats":[{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Rending Claws"}],"skills":[{"skill":"Climb","value":20},{"skill":"Perception","value":7},{"skill":"Stealth","value":7}],"environments":["warm jungles"],"organizations":["solitary","pair","band (3-5)"],"treasure":"none","source":"Lost Kingdoms","special_abilities":[{"type":"Burst of Speed","kind":"Ex","details":"Once every 1d4 rounds, a ngoga can summon a burst of energy in order to move twice its base speed in a single move action."}],"description":"In the tropical rainforests of the Kaava Lands and the Mwangi Jungle lurk animalistic offshoots of the cyclopes that once dominated the region. Known as ngogas, these half-orangutan, half-cyclops hybrids are infamous in the folktales of the Mwangi peoples, who fear them for their unpredictability and unnatural agility.\n\nIn cyclops legends, the ngogas were a gift to the Ghol-Gani from their otherworldly patrons near the collapse of the empire, magical beings infused with the brutality and insight afforded cyclopes, but lacking the intelligence that would make them viable competitors. Ghol-Gani soldiers often trained these beasts to follow them into battle and fight alongside them, and present-day cyclopes who encounter ngogas inevitably feel a sort of kinship to the similarly monocular beasts, enticing them with gifts of fruit and meat in order to gain an ally in their destructive conquests.\n\nSince the fall of Ghol-Gan, ngogas have proliferated throughout the dense jungles of central Garund, and many of their kind can be found as deep as Usaro, where the destructive Gorilla King trains them as war-mounts for his smaller minions and relies on their bestial speed to stage ambushes against any who would dare t o intrude upon his realm.","ecology":"","habitat_society":""},{"name":"Nixudaemon","cr":7,"xp":3200,"alignment":"NE","size":"Large","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+1 Dex, +10 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"hp_mods":["fast healing 2"],"fort":7,"ref":8,"will":9,"dr":"10/good or silver","immunities":["acid","daze","death effects","disease","exhaustion","fatigue","nonlethal damage","paralysis","poison","sleep","stun"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":18,"speed":[{"type":"land","speed":40}],"melee":"2 slams +12 (1d8+3), 2 +1 deadly merciful vicious whip arms +13 (1d8+4 plus grab)","space":"10 ft.","reach":"10 ft. (20 ft. with whip arms)","spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"deathwatch"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. only"}]},{"frequency":"1/day","spells":[{"spell":"temporary resurrection"}]},{"frequency":"3/day","spells":[{"spell":"heroism"},{"spell":"waves of fatigue"}]}],"strength":17,"dexterity":13,"constitution":19,"intelligence":14,"wisdom":14,"charisma":16,"baseatk":10,"cmb":14,"cmb_special":"+2 vs. disarm, +2 vs. trip, +4 vs. grapple","cmd":25,"cmd_special":"+2 vs. disarm, +2 vs. trip","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Improved Trip"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":14},{"skill":"Heal","value":13},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":10}],"languages":["Abyssal","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Abaddon)"],"organizations":["solitary","pair","corps (3-5)"],"treasure":"standard","description_visual":"This four-armed fiend has blue-green skin covered in white scars. Its two upper arms end in long, barbed whips of calloused flesh.","source":"AP 96","special_abilities":[{"type":"Damning Scourge","kind":"Su","details":"Each of a nixudaemon's upper arms functions as a Large +1 deadlyUE mercifulUE viciousUE whip. Attacks with these whips count as natural attacks for the nixudaemon, have a reach of 20 ft., and don't provoke attacks of opportunity. The whips can't be disarmed or sundered, nor can they be dropped to allow the nixudaemon to avoid being tripped because of failing a combat maneuver check to trip. The nixudaemon decides before each attack roll whether to apply the weapon's merciful special ability, its vicious special ability, both, or neither."},{"type":"Dead Tired","kind":"Su","details":"A nixudaemon's attacks drain every bit of vitality from its victims when they die. Raising a creature killed by a nixudaemon (via raise dead or another effect that restores life) requires a successful DC 20 caster level check. The restored creature gains the exhausted condition, regardless of the spell used to raise it. The DC of this caster level check is Charisma-based, and includes a +2 racial bonus. A nixudaemon can use its temporary resurrection spell-like ability without attempting this check, even if another nixudaemon killed the subject."},{"type":"Enslave","kind":"Su","details":"If a nixudaemon successfully uses its grab ability to grapple a foe with its whip attack, its tendril wraps around the victim's throat. The daemon can forgo its constrict damage and instead attempt to dominate the subject, as the spell dominate monster (Will DC 18 negates). A creature dominated by a nixudaemon is immune to fatigue, exhaustion, and pain effects. At the beginning of its turn, a dominated slave automatically receives a new saving throw to end the effect. The nixudaemon can dominate only one creature at a time per whip arm it possesses (typically two). The save DC for this ability is Charisma-based."}],"description":"Nixudaemons, or \"toil daemons,\" epitomize death by exploitation and extreme exertion. These fiends savor the moment when a desperate scholar collapses while putting in long, unappreciated hours, or when a galley slave finally succumbs to the lash. They drive burdened subjects before them to great effect, even resurrecting fallen servants for a brief time to complete vital tasks. Their skill for squeezing the last bit of energy from those under their supervision makes them invaluable to slavers, who pay the daemons in coin, information, and souls for their aid.\n\nNixudaemons exemplify the cruelty and disdain all daemonkind display toward the living. They lash out at their subjects, whipping the life out of them slowly. If it serves the daemon's purposes, or if time allows for another game of torture, a nixudaemon will revive its subject for another day. Typically, a nixudaemon uses this ability to incite a band of slaves to work harder; it dominates the weakest members of the workers to temporarily bolster them, then saps their last ounce of strength before discarding them as spent husks.\n\nMost nixudaemons stand 10 ft. tall and weigh 600 pounds. Sages report that the fiends grow larger and stronger as they age, absorbing the weariness of their victims over centuries. The greatest toil daemons are said to tower over their younger cousins, growing additional whip-arms and learning powerful spells that exhaust or even kill those who dare offend them.\n\nEcology\n\nNixudaemons roam the shores of the Styx. The daemons use their impressive reach to press new souls into service as soon as the doomed arrive on Abaddon, throwing the\n\nill-fated souls into enormous slave pens and hauling them to the realms of wealthy customers. Nixudaemons frequently visit the Material Plane, where greedy despots and desperate commandants pay high prices to the daemons in exchange for providing additional labor.\n\nRituals designed to call nixudaemons must be conducted while an intelligent, mortal creature labors physically, and the daemon's preferred sacrifice is working that creature to death as part of the ritual. One ancient story alleges that a mighty hero among an oppressed people worked for weeks, dragging great stone blocks to build a grand ziggurat. When he finally fell, the story claims, his death summoned a nixudaemon over 30 ft. tall that lashed out with a dozen whips.\n\nNixudaemons despise laziness in both mortals and outsiders. They work their subjects past the point of exhaustion or death as suits their current needs. The nixudaemons view other creatures as weak or prone to sloth, challenging even other daemons they perceive as less than diligent.\n\nHabitat & Society\n\nNixudaemons occupy the role of merchants in daemonic society. They buy and sell the hunted, as Abaddon petitioners are known, when not outright capturing or stealing them. Powerful mortal slavers sometimes increase the value of their wares by hiring a summoned nixudaemon to drive slaves to maximum efficiency, but such arrangements still benefit Abaddon in the end. While summoned to the material world, nixudaemons obtain multiple forms of currency for the Four Horsemen's coffers. They engage in a dark form of proselytization, beating those who grow weary in their work and spreading the belief among the oppressed that there is no hope of recognition or rest. More discerning nixudaemons assail the mortal merchant classes, driving entire firms to adopt competitive climates until the stress of achievement reveals itself in the form of failing health, or pushing lone inventors to complete magical theories with their dying breaths. Because soft, wealthy mortals rarely succumb to the temptation to work themselves to death, some nixudaemons have been known to engineer the sale of wealthy scions into slavery, as their nightly sobbing and rapidly developing sores are music to the toil daemons' ears.\n\nNixudaemons understand the value of teamwork and work tirelessly together to great effect. In service to mortals and greater daemons, they have driven hordes\n\nof slaves to erect legendary monuments. They revel in the misery they cause, and the crack of their whips against backs and around necks.\n\nWhile their industrious natures and affinities for mortal business make them useful to each of the Four Horsemen, most of nixudaemons serve Szuriel, Trelmarixian, and the daemonic harbingers that scheme below them. The Horseman of War uses them as morale officers-a most effective paradox during the heat of battle. She also maintains special units of indentured prisoners under nixudaemon care, always breaking her promise to send her weary combatants home after a costly battle. The Horseman of Famine offers mere crumbs for sustenance to his legions of soldiers and slaves. He takes delight in using pet nixudaemons to drive his legions past their limits, accelerating their spiritual and physical starvation.","ecology":"Nixudaemons roam the shores of the Styx. The daemons use their impressive reach to press new souls into service as soon as the doomed arrive on Abaddon, throwing the\n\nill-fated souls into enormous slave pens and hauling them to the realms of wealthy customers. Nixudaemons frequently visit the Material Plane, where greedy despots and desperate commandants pay high prices to the daemons in exchange for providing additional labor.\n\nRituals designed to call nixudaemons must be conducted while an intelligent, mortal creature labors physically, and the daemon's preferred sacrifice is working that creature to death as part of the ritual. One ancient story alleges that a mighty hero among an oppressed people worked for weeks, dragging great stone blocks to build a grand ziggurat. When he finally fell, the story claims, his death summoned a nixudaemon over 30 ft. tall that lashed out with a dozen whips.\n\nNixudaemons despise laziness in both mortals and outsiders. They work their subjects past the point of exhaustion or death as suits their current needs. The nixudaemons view other creatures as weak or prone to sloth, challenging even other daemons they perceive as less than diligent.","habitat_society":"Nixudaemons occupy the role of merchants in daemonic society. They buy and sell the hunted, as Abaddon petitioners are known, when not outright capturing or stealing them. Powerful mortal slavers sometimes increase the value of their wares by hiring a summoned nixudaemon to drive slaves to maximum efficiency, but such arrangements still benefit Abaddon in the end. While summoned to the material world, nixudaemons obtain multiple forms of currency for the Four Horsemen's coffers. They engage in a dark form of proselytization, beating those who grow weary in their work and spreading the belief among the oppressed that there is no hope of recognition or rest. More discerning nixudaemons assail the mortal merchant classes, driving entire firms to adopt competitive climates until the stress of achievement reveals itself in the form of failing health, or pushing lone inventors to complete magical theories with their dying breaths. Because soft, wealthy mortals rarely succumb to the temptation to work themselves to death, some nixudaemons have been known to engineer the sale of wealthy scions into slavery, as their nightly sobbing and rapidly developing sores are music to the toil daemons' ears.\n\nNixudaemons understand the value of teamwork and work tirelessly together to great effect. In service to mortals and greater daemons, they have driven hordes\n\nof slaves to erect legendary monuments. They revel in the misery they cause, and the crack of their whips against backs and around necks.\n\nWhile their industrious natures and affinities for mortal business make them useful to each of the Four Horsemen, most of nixudaemons serve Szuriel, Trelmarixian, and the daemonic harbingers that scheme below them. The Horseman of War uses them as morale officers-a most effective paradox during the heat of battle. She also maintains special units of indentured prisoners under nixudaemon care, always breaking her promise to send her weary combatants home after a costly battle. The Horseman of Famine offers mere crumbs for sustenance to his legions of soldiers and slaves. He takes delight in using pet nixudaemons to drive his legions past their limits, accelerating their spiritual and physical starvation."},{"name":"Nogitsune","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["kitsune","native","oni","shapechanger"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":21,"ac_touch":18,"ac_flat_footed":13,"ac_mods":"+7 Dex, +1 dodge, +3 natural","hp":80,"hd":"7d10+42","hdvalue":7,"hp_mods":["regeneration 5 (acid or fire)"],"fort":8,"ref":12,"will":8,"defensive_abilities":["evasion"],"sr":18,"speed":[{"type":"land","speed":50},{"type":"climb","speed":50}],"melee":"bite +14 (1d6+4), 2 claws +14 (1d4+2 plus poison)","ranged":"mwk dart +15 (1d4+4 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"contagious whisper"},{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect thoughts"}]},{"frequency":"at-will","spells":[{"spell":"feather fall"},{"spell":"jump"},{"spell":"obscuring mist"}]},{"frequency":"1/day","spells":[{"spell":"displacement"},{"spell":"haste"},{"spell":"shadow walk"}]}],"strength":18,"dexterity":25,"constitution":22,"intelligence":17,"wisdom":16,"charisma":19,"baseatk":7,"cmb":11,"cmd":29,"feats":[{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":17,"special":"+25 jump"},{"skill":"Appraise","value":5},{"skill":"Bluff","value":14},{"skill":"Climb","value":16},{"skill":"Diplomacy","value":7},{"skill":"Disable Device","value":16},{"skill":"Disguise","value":13},{"skill":"Escape Artist","value":17},{"skill":"Knowledge (arcana)","value":5},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":11},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":17},{"skill":"Swim","value":5}],"languages":["Common","Draconic","Fey","Giant"],"sq":[{"type":"change shape","details":"Small or Medium humanoid or animal, alter self or beast shape I"},{"type":"fleet distraction"},{"type":"poison use"}],"environments":["any urban"],"organizations":["solitary"],"treasure":"double (four masterwork darts, 5 doses of blue whinnis poison)","description_visual":"This fox-headed humanoid has a sleek, feminine form that moves with seductive grace. As she steps into a defensive posture, a mass of bushy tails flicks at the air above her back and she reveals teeth flecked with blood.","source":"AP 50","special_abilities":[{"type":"Contagious Whisper","kind":"Su","details":"As a standard action, a nogitsune can influence a target she speaks to as per the spell suggestion. The target must succeed at a DC 17 Will save or be affected by this effect. In addition to being subject to suggestion's normal effects, any creature affected by the contagious whisper can pass the enchantment on to other targets. Doing so requires the target to communicate the nogitsune's suggestion, forcing the new target to save as if it were the initial target. If such a secondary target resists the contagious whisper, it is unaffected, but this doesn't remove the suggestion from the initial target. Failing the save puts another creature under the nogitsune's compulsion. Newly affected creatures are also able to spread the suggestion. A nogitsune's compelling whisper can affect a number of creatures equal to the its Hit Dice and lasts for a number of hours equal to its Hit Dice. Creatures that successfully save versus the nogitsune's compelling whisper (as a primary or secondary target) cannot be affected by that particular nogitsune's compelling whisper for 24 hours. The save DC is Charisma-based."},{"type":"Fleet Distraction","kind":"Su","details":"A nogitsune can make a Bluff check or use its obscuring mist spell-like ability as a swift action in any round in which it moves up to half its base land speed."},{"type":"Poison Use","kind":"Ex","details":"Nogitsune are skilled in the use of poison and never risk accidentally poisoning themselves. Their aptitude is such that they often paint their weapons and nails with blue whinnis. Blue Whinnis: injury; save Fort DC 14; frequency 1/round for 2 rounds; initial effect 1 Con damage; secondary effect unconsciousness for 1d3 hours; cure 1 save"}],"description":"Nogitsune are created when oni spirits take over the bodies of kitsune (sagacious humanoid fox-creatures). The resultant possession creates a creature with the kitsune's foxlike grace and cunning and infuses it with the destructive power of an oni. Nogitsune are always female, and resemble shapely humans with a covering of fur and a fox's head. A nogitsune's fur color varies and can be orange and white, grey, pure white, or even black. Whenever nogitsune use their shapechanging abilities to assume a humanoid form, they still evince somewhat pointed, vulpine features. In addition, any hair on their assumed form betrays the natural coloration of their pelts. Nogitsune stand between 5 and 5-1/2 ft. tall and weigh just over 100 pounds.\n\nEcology\n\nOni manifest themselves in different ways based on the creatures they take as vessels for their depraved wrath. They take particular joy in corrupting kitsune to form nogitsune, delighting in turning the mystical creatures into deadly killers and spreaders of woe. Most nogitsune become spies or assassins. Though they need no real reason to kill others, the coin they receive for their services allows them to afford the other vices they enjoy, such as pleasures of the flesh and excesses of drink and narcotics (when available). Nogitsune are deft killers because of their speed, grace, and spell-like abilities. Those who have seen them and lived tell tales of these oni running toward walls at blinding speed and then simply continuing upward to vault the wall's crown as if it were no more difficult to walk on than the ground. Still others\n\nclaim that nogitsune can dive into a shadow like a pool of water and disappear, while others mention the cloud of smoke that nogitsune often use to escape pursuit, even when running full speed.\n\nAlthough they often don human form to disguise themselves for the purpose of infiltration, nogitsune prefer to stalk and kill prey in their natural form. This gives the creatures the choice of whether to use manufactured weapons or their own sharp claws and deadly bite. When wielding weapons, all nogitsune enjoy using poison, whenever possible employing toxins and venoms that don't kill outright (unless a contract so requires it) but rather render the victims unconscious or helpless. This gives the oni the joy of dealing the killing blow with their jaws and slaking their bloodlust in abject savagery.\n\nA nogitsune's most feared weapon, however, is its contagious whisper. This powerful compulsion, often whispered into the victim's ear in honeyed tones, not only forces the targeted creature to believe whatever lie the nogitsune crafts, but also infects the subject of the contagious whisper with a corruptive echo of deceit that causes the victim to unknowingly pass on the nogitsune's suggestion to others. Nogitsune may use this ability to convince a successive series of servants to open all of the doors to a well-guarded castle, or to make a host of witnesses believe they saw an innocent man commit a brutal crime that was really the oni's own handiwork.\n\nHabitat & Society\n\nNogitsune inhabit large urban areas, where they can have their pick of a nearly endless stream of victims. Occasionally they will inhabit a town or village in the countryside, but such locales are always in the shadow of a large castle or estate that can provide additional opportunities to stalk and murder others. Wherever they choose to dwell, nogitsune lair in the seediest districts, where drugs, brothels, and crime are rampant. These areas not only discourage chase by would-be pursuers, but also place the oni in the midst of people who society generally doesn't miss if and when a contract doesn't slake the creature's bloodlust.\n\nThose looking to hire a nogitsune can do so, but such a practice is both costly and dangerous. Although little binds a nogitsune to its accepted contract when it receives payment, most nogitsune happily carry out their orders for the sheer joy of bringing death to another. But many who foolishly hire nogitsune to do their killing find themselves the next victim once the initial target is slain. Nogitsune have little honor, and such treachery not only feeds their bloodlust, but also leaves fewer witnesses.\n\nNogitsune prefer to lead solitary lives and be in command of their own foul fates. Thus, most avoid associating with more powerful creatures, other oni, or even other nogitsune. Those honorable samurai and good ninja who have fought and killed nogitsune recount seeing a conf licted and turbulent anger within the creatures, as if the once-righteous kitsune within a nogitsune constantly battles to reassert control. Although there is no record of such a reversal occurring, many believe that these malevolent oni drown themselves in death and bloodshed in order to extinguish the last vestiges of the creatures they were before.","ecology":"Oni manifest themselves in different ways based on the creatures they take as vessels for their depraved wrath. They take particular joy in corrupting kitsune to form nogitsune, delighting in turning the mystical creatures into deadly killers and spreaders of woe. Most nogitsune become spies or assassins. Though they need no real reason to kill others, the coin they receive for their services allows them to afford the other vices they enjoy, such as pleasures of the flesh and excesses of drink and narcotics (when available). Nogitsune are deft killers because of their speed, grace, and spell-like abilities. Those who have seen them and lived tell tales of these oni running toward walls at blinding speed and then simply continuing upward to vault the wall's crown as if it were no more difficult to walk on than the ground. Still others\n\nclaim that nogitsune can dive into a shadow like a pool of water and disappear, while others mention the cloud of smoke that nogitsune often use to escape pursuit, even when running full speed.\n\nAlthough they often don human form to disguise themselves for the purpose of infiltration, nogitsune prefer to stalk and kill prey in their natural form. This gives the creatures the choice of whether to use manufactured weapons or their own sharp claws and deadly bite. When wielding weapons, all nogitsune enjoy using poison, whenever possible employing toxins and venoms that don't kill outright (unless a contract so requires it) but rather render the victims unconscious or helpless. This gives the oni the joy of dealing the killing blow with their jaws and slaking their bloodlust in abject savagery.\n\nA nogitsune's most feared weapon, however, is its contagious whisper. This powerful compulsion, often whispered into the victim's ear in honeyed tones, not only forces the targeted creature to believe whatever lie the nogitsune crafts, but also infects the subject of the contagious whisper with a corruptive echo of deceit that causes the victim to unknowingly pass on the nogitsune's suggestion to others. Nogitsune may use this ability to convince a successive series of servants to open all of the doors to a well-guarded castle, or to make a host of witnesses believe they saw an innocent man commit a brutal crime that was really the oni's own handiwork.","habitat_society":"Nogitsune inhabit large urban areas, where they can have their pick of a nearly endless stream of victims. Occasionally they will inhabit a town or village in the countryside, but such locales are always in the shadow of a large castle or estate that can provide additional opportunities to stalk and murder others. Wherever they choose to dwell, nogitsune lair in the seediest districts, where drugs, brothels, and crime are rampant. These areas not only discourage chase by would-be pursuers, but also place the oni in the midst of people who society generally doesn't miss if and when a contract doesn't slake the creature's bloodlust.\n\nThose looking to hire a nogitsune can do so, but such a practice is both costly and dangerous. Although little binds a nogitsune to its accepted contract when it receives payment, most nogitsune happily carry out their orders for the sheer joy of bringing death to another. But many who foolishly hire nogitsune to do their killing find themselves the next victim once the initial target is slain. Nogitsune have little honor, and such treachery not only feeds their bloodlust, but also leaves fewer witnesses.\n\nNogitsune prefer to lead solitary lives and be in command of their own foul fates. Thus, most avoid associating with more powerful creatures, other oni, or even other nogitsune. Those honorable samurai and good ninja who have fought and killed nogitsune recount seeing a conf licted and turbulent anger within the creatures, as if the once-righteous kitsune within a nogitsune constantly battles to reassert control. Although there is no record of such a reversal occurring, many believe that these malevolent oni drown themselves in death and bloodshed in order to extinguish the last vestiges of the creatures they were before."},{"name":"Nymph","cr":7,"xp":3200,"alignment":"CG","size":"Medium","type":"fey","init":5,"senses":[{"type":"low-light vision"}],"auras":["blinding beauty (30 ft., DC 21)"],"ac":23,"ac_touch":23,"ac_flat_footed":17,"ac_mods":"+7 deflection, +5 Dex, +1 dodge","hp":60,"hd":"8d6+32","hdvalue":8,"fort":13,"ref":18,"will":16,"dr":"10/cold iron","speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"melee":"mwk dagger +10 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"stunning glance"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"}]}],"spellsprepared_caster_level":7,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":4,"spell_slots":1,"spells":[{"spell":"summon nature's ally IV"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"call lightning"},{"spell":"cure moderate wounds"},{"spell":"water breathing"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"barkskin"},{"spell":"flame blade"},{"spell":"resist energy"},{"spell":"tree shape"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"charm animal"},{"spell":"endure elements"},{"spell":"entangle"},{"spell":"obscuring mist"},{"spell":"produce flame"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"stabilize"}]}],"strength":10,"dexterity":21,"constitution":18,"intelligence":16,"wisdom":17,"charisma":25,"baseatk":4,"cmb":9,"cmd":27,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Diplomacy","value":18},{"skill":"Escape Artist","value":16},{"skill":"Handle Animal","value":15},{"skill":"Heal","value":11},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":16},{"skill":"Swim","value":19}],"languages":["Common","Sylvan"],"sq":[{"type":"inspiration"},{"type":"unearthly grace"},{"type":"wild empathy","details":"+21"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"standard (dagger)","description_visual":"A delicate figure rises from the water, her long ears tapering to points above her head, her beauty painful in its perfection.","source":"PFRPG Bestiary","special_abilities":[{"type":"Blinding Beauty","kind":"Su","details":"This ability affects all humanoids within 30 ft. of a nymph. Those who look directly at a nymph must succeed on a DC 21 Fortitude save or be blinded permanently. A nymph can suppress or resume this ability as a free action. The save DC is Charisma-based."},{"type":"Inspiration","kind":"Su","details":"A nymph can choose an intelligent creature to inspire and serve as a muse by giving that creature some token of her affection (typically a lock of her hair). As long as the nymph retains her favor for this creature and as long as the creature carries the nymph's token, the creature gains a +4 insight bonus on all Will saving throws, Craft checks, and Perform checks. A bard who has a nymph for a muse in this way can use his bardic performance for an additional number of rounds per day equal to his nymph muse's Charisma modifier. The nymph retains a link to her token and its carrier as if she had cast a status spell on the carrier. The nymph can end this effect at any time as a free action. A single nymph may only inspire one creature at a time in this manner. Spells A nymph casts spells as a 7th-level druid, but cannot swap out prepared spells to cast summon spells."},{"type":"Stunning Glance","kind":"Su","details":"As a standard action, a nymph can stun a creature within 30 ft. with a look. The target must succeed on a DC 21 Fortitude save or be stunned for 2d4 rounds. The save DC is Charisma-based."},{"type":"Unearthly Grace","kind":"Su","details":"A nymph adds her Charisma modifier as a racial bonus on all her saving throws, and as a deflection bonus to her Armor Class."},{"type":"Wild Empathy","kind":"Su","details":"This works like the druid's wild empathy class feature, except the nymph has a +6 racial bonus on the check. The nymph's effective druid level is equal to her HD for determining her total modifer to the check."}],"description":"Many have lost their lives in vain search of the beauty of the nymph, and many more to the madness and obsession their grace has upon minds and bodies unprepared for their companionship. Yet the nymph herself isn't a cruel creature-a guardian of nature's purest places and most beautiful realms, she treats those who respect her and her abode with kindness, and may even favor someone who takes her fancy with magical gifts. Yet those who would seek to abuse or harm her or her home quickly find that behind her beauty is a fierce protector more than capable of defending her charge.","ecology":"","habitat_society":""},{"name":"Oceanid","cr":7,"xp":3200,"alignment":"CN","size":"Medium","type":"fey","subtypes":["water"],"init":8,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"30 ft. (in water only)"}],"ac":21,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 Dex, +1 dodge, +6 natural","hp":76,"hd":"9d6+45","hdvalue":9,"hp_mods":["fast healing 10 (in salt water only)"],"fort":8,"ref":10,"will":10,"dr":"10/cold iron","immunities":["acid"],"resists":[{"type":"cold","value":30}],"weaknesses":["vulnerable to fire","water dependency","water magic"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":80}],"melee":"slam +6 (1d4+3)","ranged":"waterspout +8 (7d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"water telekinesis"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"speak with animals","details":"sea creatures only"}]},{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"create water"},{"spell":"purify food and drink","details":"water only"},{"spell":"water breathing","details":"up to 9 creatures at a time"}]},{"frequency":"1/day","spells":[{"spell":"control weather"}]},{"frequency":"3/day","spells":[{"spell":"control winds"},{"spell":"summon nature's ally V","details":"sea creatures or water elementals only"}]}],"strength":14,"dexterity":19,"constitution":20,"intelligence":14,"wisdom":19,"charisma":21,"baseatk":4,"cmb":6,"cmd":26,"feats":[{"feat":"Combat Casting"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"}],"skills":[{"skill":"Diplomacy","value":17},{"skill":"Handle Animal","value":14},{"skill":"Intimidate","value":14},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":16},{"skill":"Swim","value":22}],"languages":["Aquan","Common","Sylvan","speak with animals (sea creatures only)"],"sq":[{"type":"waveglide"}],"environments":["any oceans"],"organizations":["solitary"],"treasure":"standard","description_visual":"This beautiful woman is clad only in sea foam and her long, white hair, which cascades over her body.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Water Dependency","kind":"Ex","details":"An oceanid can survive out of the water for 1 hour per point of Constitution. After this limit, she takes 1 point of Constitution damage each hour until immersed in salt water."},{"type":"Water Magic","kind":"Su","details":"An oceanid can use her spell-like abilities only when she is in the ocean or within 1 mile of the ocean."},{"type":"Water Telekinesis","kind":"Su","details":"When immersed in water, an oceanid can manipulate water to affect creatures and objects within 500 ft. that are in contact with the same body of water. This functions as the combat maneuver form of the telekinesis spell (caster level 9th, combat maneuver bonus +14), including the need to maintain concentration. This ability also allows her to create a small waterspout as a standard action once per round, striking an opponent within 100 ft. with a blast of water as a ranged attack that deals 7d6 points of bludgeoning damage."},{"type":"Waveglide","kind":"Su","details":"An oceanid can create waves and currents to double or halve the speed of creatures or objects traveling on the surface of the water, affecting up to 100 contiguous 5-foot squares in a shapeable area (typically enough for one warship or two small sailing ships). This ability has a range of 1,000 ft., requires line of effect to some part of the area, and lasts as long as the oceanid concentrates. An unwilling target can ignore the effect for 1 round by succeeding at a DC 19 Will saving throw. The save DC is Charisma-based."}],"description":"Aquatic kin of nymphs and dryads, oceanids are fey bound to the sea. They can live in lakes, rivers, or oceans, but truly thrive only in salt water. The mood of an oceanid can change with little warning-they are quick to love and even quicker to anger. An oceanid can be quite helpful toward mortals and their vessels- particularly if the mortals indulge her extreme vanity. Though silver-tongued people skilled at flattery might earn her help, they might also be lured away to join the oceanid under the sea until she grows bored with them. When an oceanid is in the water, the lower half of her body transforms into a pillar of water, allowing her to swim at incredible speed. When she leaves the water, this water pillar transforms into humanoid legs. However, most oceanids consider walking a chore, and avoid it when possible.","ecology":"","habitat_society":""},{"name":"Oracular Cyclops","cr":7,"xp":3200,"alignment":"NE","size":"Large","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"low-light vision"}],"ac":21,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+1 Dex, +4 insight, +7 natural, -1 size","hp":91,"hd":"14d8+28","hdvalue":14,"fort":11,"ref":5,"will":7,"speed":[{"type":"land","speed":30}],"melee":"mwk Large greataxe +15 (3d6+7/x3)","ranged":"heavy crossbow +10 (2d8/19-20)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"augury"}]},{"frequency":"3/day","spells":[{"spell":"divination"}]}],"strength":21,"dexterity":12,"constitution":15,"intelligence":12,"wisdom":17,"charisma":10,"baseatk":10,"cmb":16,"cmd":31,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Intimidate","value":9},{"skill":"Perception","value":20},{"skill":"Profession (soothsayer)","value":16},{"skill":"Sense Motive","value":17},{"skill":"Survival","value":8}],"languages":["Common","Cyclops","Giant"],"sq":[{"type":"greater flash of insight"},{"type":"protective foresight"}],"organizations":["solitary","conclave (2-6)","tribe (7-18)"],"treasure":"standard (hide armor, greataxe, heavy crossbow)","description_visual":"Clothed in loose robes and wearing jewelry, this one-eyed giant appears to hold a high station.","source":"AP 58","special_abilities":[{"type":"Greater Flash of Insight","kind":"Su","details":"Once per day as an immediate action, a cyclops can peer into an occluded visual spectrum of possible futures, gaining insight that allows it to select the exact result of one die roll before the roll is made. This effect can alter an action taken by the cyclops, and once per week the oracular cyclops can apply this ability to one creature of her choosing. The target of this boon must be within 30 ft. of the oracular cyclops and be able to be seen."},{"type":"Protective Foresight","kind":"Su","details":"An oracular cyclops can peer into the future to protect itself. This ability grants the cyclops a +4 insight bonus to AC."}],"description":"A cyclops oracle retains more of the powers of foresight than most of its kin. In addition to a cyclops's typical flash of insight ability, an oracular cyclops can share its gift with others, granting them a boon on a future challenge. While often smaller than others of its kind, an oracular cyclops gains the ability to foresee danger coming its way. The statistics above depict a cyclops who is served by a cult of worshippers, and is therefore in good health. Other oracular cyclopes are sometimes kept as chained prisoners, at the mercy of their captors.","ecology":"","habitat_society":""},{"name":"Osirionologist","cr":7,"xp":3200,"race":"Human","classes":[{"class":"bard (archaeologist)","level":8}],"alignment":"N","size":"Medium","type":"humanoid","subtypes":["human"],"init":3,"ac":19,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+5 armor, +3 Dex, +1 dodge","hp":71,"hd":"8d8+32","hdvalue":8,"fort":6,"ref":9,"will":5,"save_mods":"Ref: +2 vs. traps","defensive_abilities":["evasion","trap sense +2","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"+1 rapier +11 (1d6+2/18-20) or mwk whip +10 (1d3+1 nonlethal)","ranged":"mwk composite shortbow +10 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"archaeologist's luck 7 rounds/day","details":"+2"}],"spellsknown_caster":"bard","spellsknown_caster_level":8,"spellsknown_concentration":14,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"dispel magic"},{"spell":"good hope"},{"spell":"haste"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds"},{"spell":"glitterdust"},{"spell":"locate object"},{"spell":"pilfering hand"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"animate rope"},{"spell":"charm person"},{"spell":"comprehend languages"},{"spell":"detect secret doors"},{"spell":"grease"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"know direction"},{"spell":"mending"},{"spell":"open/close"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":12,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":8,"charisma":16,"baseatk":6,"cmb":7,"cmd":21,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Appraise","value":5},{"skill":"Climb","value":12},{"skill":"Disable Device","value":15},{"skill":"Knowledge (arcana, dungeoneering, history, religion)","value":11},{"skill":"Linguistics","value":5},{"skill":"Perception","value":14},{"skill":"Spellcraft","value":7}],"languages":["Ancient Osiriani","Common","Osiriani"],"sq":[{"type":"bardic knowledge","details":"+4"},{"type":"clever explorer","details":"+4"},{"type":"lore master","details":"1/day"},{"type":"rogue talents","details":"trap spotter, weapon training"}],"environments":["any (Osirion)"],"organizations":["solitary","pair","expedition (3-6)"],"treasure":"none","description_visual":"This human adventurer wears a long, light-colored leather coat, a wide-brimmed hat, and a belt that keeps her tools, sheathed weapons, and vials within easy reach.","source":"Osirion, Legacy Of Pharaohs","description":"An Osirionologist is a scholar who specializes in the study of Ancient Osirion. Because this lost civilization accomplished wonders unmatched by current magical and engineering knowledge and did so very suddenly after a starkly primitive beginning, many Osirionologists- including scholars, collectors, and power-hungry magical researchers from Andoran, Cheliax, Absalom, Osirion, Qadira, Katapesh, and beyond-obsess over discovering how these wonders came about.\n\nOsirionologists are often amenable to working with Pathfinders exploring the ruins of Ancient Osirion as long as they feel their academic agendas are respected. They also work as hired experts for the Aspis Consortium so they can undertake otherwise unaffordable expeditions. Naturally, most Osirionologists place their own motivations above those of their allies, and can be trusted only so long as they are moving toward their goals.","ecology":"","habitat_society":"","gear":"+1 mithral chain shirt, +1 rapier, mwk composite shortbow [+1 Str] with 20 arrows, mwk whip, elixir of fire breath, potion of cure serious wounds, potion of endure elements, potion of invisibility, antitoxin, climber's kit, grappling hook, magnifying glass, mwk thieves' tools, sunrods [5], 62 gp"},{"name":"Pairaka","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["div","evil","extraplanar","shapechanger"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"},{"type":"see in darkness"}],"ac":23,"ac_touch":15,"ac_flat_footed":18,"ac_mods":"+5 Dex, +8 natural","hp":76,"hd":"9d10+27","hdvalue":9,"fort":6,"ref":11,"will":10,"dr":"10/cold iron or good","immunities":["fire","poison","disease"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10}],"sr":22,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"2 claws +14 (1d6+3 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"lustful dreams"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"dimension door","details":"self plus 50 lbs. of objects only"},{"spell":"misdirection"}]},{"frequency":"1/day","spells":[{"spell":"insect plague"},{"spell":"summon","details":"level 3, 1d4 dorus 50%"}]}],"strength":17,"dexterity":20,"constitution":16,"intelligence":14,"wisdom":18,"charisma":24,"baseatk":9,"cmb":12,"cmd":27,"feats":[{"feat":"Deceitful"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Diplomacy","value":18},{"skill":"Disguise","value":18},{"skill":"Fly","value":16},{"skill":"Intimidate","value":16},{"skill":"Knowledge (local)","value":13},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":17}],"languages":["Abyssal","Celestial","Infernal","telepathy 100 ft."],"sq":[{"type":"change shape","details":"any Small or Medium animal or humanoid; polymorph"}],"environments":["any (Abaddon)"],"organizations":["solitary"],"treasure":"standard","description_visual":"Blue-skinned and draped in revealing attire, this humanoid fiend has a sultry gaze suggesting all manner of debased pleasures.","group":"Div","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Disease","kind":"Su","details":"A pairaka carries two diseases. Its claws infect targets with bubonic plague, and any willing contact with its skin (such as through caressing, grappling, or more) exposes victims to the shakes. Bubonic Plague: Claw-injury; save Fort DC 17; onset 1 day; frequency 1/ day; effect 1d4 Str damage, 1 Cha damage, and target is fatigued; cure 2 consecutive saves. Shakes: Contact; save Fort DC 17; onset 1 day; frequency 1/day; effect 1d8 Dex damage; cure 2 consecutive saves."},{"type":"Lustful Dreams","kind":"Su","details":"Pairakas can torment sleeping creatures. While an intelligent creature sleeps, a pairaka can slip into the target's mind and twist its dreams to lusty nocturnal visions. The victim must be asleep for the pairaka to use this ability and the pairaka must be within 100 ft. If the victim fails a DC 21 Will save, it experiences vivid hallucinations of a lurid nature that leave it breathless and fatigued upon waking. The victim, even a depraved soul, rarely considers the sexual nature of these dreams enjoyable, as the images exploit any number of taboos the pairaka suspects its victim might harbor. The save DC is Charisma-based. Creatures that don't sleep or dream are immune to this effect."}],"description":"A sensual pairing of seduction and destruction, pairakas embody the corruptive nature of unbridled lust. Pairakas spend little time in their true form while on the Material Plane, choosing to cloak themselves instead in alluring forms to seduce potential victims, ruin relationships, and foment obsession. In its true form, a pairaka's body is a foul landscape of blazing rashes, oozing pustules, and taut blisters suggestive of the corruptions it harbors, bodily and spiritually.\n\nPairakas pride themselves on perversion. They love nothing more than turning lovers against one another or destroying the bonds of friendship. Pairakas feed off this slow torment and savor each broken heart or disappointment. They use lust and sexuality as their primary tools, wielding taboos and carnal appetites to sever once-friendly relationships. Pairakas also use their seduction to spread disease, charming victims into physical contact.\n\nJust as all other divs suffer a weakness, pairakas cannot stand the color red. They never wear the color or enter a place that is painted red, and they always attack creatures that are garbed in clothes of a crimson hue first.\n\nPairakas stand 6 ft. tall and weigh around 150 pounds. Their skin color varies widely between individuals.","ecology":"","habitat_society":""},{"name":"Pukwudgie","cr":7,"xp":3200,"alignment":"NE","size":"Small","type":"monstrous humanoid","subtypes":["shapechanger"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"deathwatch"},{"type":"detect good"},{"type":"detect magic"}],"ac":20,"ac_touch":16,"ac_flat_footed":15,"ac_mods":"+4 Dex, +1 dodge, +4 natural, +1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":7,"ref":10,"will":10,"immunities":["poison"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +14 (1d4+2 plus poison)","ranged":"2 quills +15 (1d4+2 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+3d6"},{"type":"spawn undead"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"deathwatch"},{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"command undead"},{"spell":"produce flame"}]},{"frequency":"1/day","spells":[{"spell":"nondetection"}]},{"frequency":"3/day","spells":[{"spell":"animate dead"},{"spell":"death knell"},{"spell":"invisibility"},{"spell":"ray of enfeeblement"},{"spell":"scare"}]}],"strength":14,"dexterity":18,"constitution":19,"intelligence":15,"wisdom":14,"charisma":19,"baseatk":9,"cmb":10,"cmd":25,"feats":[{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (quill)"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Heal","value":10},{"skill":"Knowledge (arcana)","value":11},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":13},{"skill":"Spellcraft","value":11},{"skill":"Stealth","value":16}],"languages":["Common","Draconic","Infernal"],"sq":[{"type":"change shape","details":"porcupine, beast shape II"}],"environments":["any hills","any mountains","temperate forests"],"organizations":["solitary","pair","cult (3-10)"],"treasure":"standard","description_visual":"A merging of an emaciated man and a porcupine, this sinister creature smells of death and decay.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Spawn Undead","kind":"Su","details":"Any creature slain by a pukwudgie's poisonous quills rises in 24 hours as a zombie. Undead created by this ability are not immediately under the control of a pukwudgie, but they receive a -4 penalty on saves against a pukwudgie's control undead spell-like ability."},{"type":"Poison","kind":"Su","details":"Claw or quill-injury; save Fort DC 18; frequency 1/round for 6 rounds; effect 1d3 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Quills","kind":"Ex","details":"A pukwudgie can fire two of its quills as a ranged attack as a standard action. These quills have a range increment of 40 ft. Any creature attacking a pukwudgie with light or one-handed melee weapons, natural weapons, or an unarmed strike takes 1d3 points of piercing damage. A creature that grapples a pukwudgie takes 2d4 points of piercing damage. Anyone who takes damage from these quills is also exposed to the pukwudgie's poison."}],"description":"The vile pukwudgie is a small, hunchbacked humanoid covered with long, sharp quills. These quills, like those of a porcupine, help protect the small creature but are also dangerous offensive weapons, for the quills hold a deadly poison that animates those it slays as zombies. This necromantic nature, along with their penchant for torment and sadistic ways, makes pukwudgies evil to the core. A pukwudgie stands 3-1/2 ft. tall and weighs a little more than 30 pounds.\n\nPukwudgies are frequently found in the company of undead. This retinue usually consists of zombies and skeletons created via their poisonous quills ability or their ability to animate dead bodies. They have a strong preference for animating the bodies of dead animals over other creatures, and often use undead animals as mounts.\n\nA pukwudgie usually stays away from well-traveled areas and humanoid settlements, but may sometimes slip into small villages in the night to steal children. The little horrors enjoy the tender flesh of newborn babies immensely, and are often willing to go through great personal risk to secure infantile repasts when they are available. Their delight in arson only further makes them a bane of small villages.","ecology":"","habitat_society":""},{"name":"Qallupilluk","cr":7,"xp":3200,"alignment":"LE","size":"Medium","type":"monstrous humanoid","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["cloying scent (15 ft.)"],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+2 Dex, +7 natural","hp":76,"hd":"8d10+32","hdvalue":8,"fort":6,"ref":10,"will":8,"dr":"5/cold iron","resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"swim","speed":40}],"melee":"bite +13 (1d6+5), 2 claws +13 (1d6+5 plus grab)","ranged":"javelin +10 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"curse of scales"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"water breathing"}]},{"frequency":"1/day","spells":[{"spell":"commune with nature"},{"spell":"divination"}]},{"frequency":"3/day","spells":[{"spell":"charm animal"},{"spell":"charm person"},{"spell":"chill metal"},{"spell":"sleet storm"}]}],"strength":20,"dexterity":14,"constitution":19,"intelligence":13,"wisdom":15,"charisma":14,"baseatk":8,"cmb":13,"cmb_special":"+4 vs. grapple","cmd":25,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Stand Still"}],"skills":[{"skill":"Knowledge (nature)","value":9},{"skill":"Perception","value":13},{"skill":"Stealth","value":13},{"skill":"Survival","value":13},{"skill":"Swim","value":23}],"languages":["Aklo","Aquan","Common","Giant"],"sq":[{"type":"amphibious"}],"environments":["cold oceans"],"organizations":["solitary","family (2-6 plus 1-4 aquatic monsters)"],"treasure":"standard","description_visual":"This hag's lumpy hide, tangled black hair, and ragged garments drip with icy water, though she has a curiously sweet smell.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Cloying Scent","kind":"Su","details":"Qallupilluks exude a vaguely sweet and unexpectedly pleasant briny scent. This smell comforts and distracts humanoids and animals that come within 15 ft. of the qallupilluk, causing such creatures to take a -2 penalty on saves against mind-affecting effects."},{"type":"Curse of Scales","kind":"Su","details":"If a qallupilluk grapples a Medium or Small humanoid opponent, her target begins transforming into an aquatic monster. Starting on the third consecutive round of grappling, the grappled target must succeed at a DC 18 Fortitude save every round or fully transform into a grindylow, reefclaw, bunyip, merrow, or scrag. Once fully transformed, the creature is slavishly devoted to the qallupilluk that created it. If the qallupilluk is slain, the creature loses this devotion but remains transformed. The transformation ends after 1 hour or if the creature is slain. A qallupilluk can make this transformation permanent by performing a ritual that takes 10 minutes and deals 30 points of damage to the qallupilluk. This is a curse and polymorph effect. The save DC is Constitution-based."}],"description":"A qallupilluk is a sinister and much-dreaded haglike denizen of cold seas. An ambush predator, she waits near gaps and weak points in the ice and listens for the footsteps of creatures above, sometimes humming or tapping on the ice like a trapped seal in the hope of drawing the curious within range of her alluring scent. When one grabs a victim, she either drowns her prey, saving the body to eat later, or transforms her prey into a monstrous servant that she treats as her own child-and eventually, as a mate. All qallupilluks are female, but they can reproduce with other aquatic monsters. Their offspring are always qallupilluks. Qallupilluks may craft hovels or lodges from stone or coral on the seabed. A few craft semipermanent homes in the submerged recesses of icebergs. They often know fragments of ancient and obscure natural secrets.","ecology":"","habitat_society":""},{"name":"Quetzalcoatlus","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 Dex, +1 dodge, +7 natural, -2 size","hp":82,"hd":"11d8+33","hdvalue":11,"fort":10,"ref":12,"will":5,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"clumsy"}],"melee":"bite +13 (2d8+7/x3), 2 wings +8 (1d6+3)","space":"15 ft.","reach":"15 ft.","strength":25,"dexterity":17,"constitution":17,"intelligence":2,"wisdom":14,"charisma":12,"baseatk":8,"cmb":17,"cmd":31,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":-6},{"skill":"Perception","value":13}],"sq":[{"type":"razor-sharp beak"}],"environments":["any plains","any swamps","warm coastlines"],"organizations":["solitary","pair","flock (3-6)"],"treasure":"none","description_visual":"A brightly colored creature swoops down to land on the branch above. Its head is overly large, with a mouth full of sharp teeth and bright, shiny eyes. The thing chirps, lashes its long thin tail, and then with a flap of leathery wings is in the air once again.","group":"Pterosaur","source":"AP 37","special_abilities":[{"type":"Razor-Sharp Beak","kind":"Ex","details":"A quetzalcoatlus's razor-sharp beak has a critical modifier of x3."}],"description":"Pterosaurs are often found in regions where dinosaurs and other prehistoric creatures are commonly encountered, yet they are not dinosaurs themselves. The pteranodon is the most well known and widespread of these flying reptiles, but numerous other species exist, such as the relatively small rhamphorhynchus, the venomous dimorphodon, and the lumbering, giraffe-sized quetzalcoatlus. While the larger pterosaurs are awkward fliers, the smaller ones can be quite agile and quick. Pterosaurs generally dwell on coastlines, along rivers, or near swamps or lakes, for the majority of their diet consists of fish snatched from the water in daring dives. Pterosaurs are quite territorial, though, and most won't hesitate to swoop down and hiss, shriek, and attack things their size or larger.\n\nQuetzalcoatlus Perhaps the largest of the pterosaurs, the quetzalcoatlus (known to some as the \"swamp stalker\" and others by the misnomer of \"dragonling\") is truly an awe-inspiring sight in the air, with its impressive 40-foot wingspan. On the ground, this creature's profile bears an uncanny resemblance to that of a giraffe, save for the fact that the folded wings arch up to either side of its lightly feathered body, and its head bears a horrific, razor-sharp beak. Unlike dimorphodons, quetzalcoatluses are difficult to train. Handle Animal checks made to train one of these looming pterosaurs take a -4 penalty.","ecology":"","habitat_society":""},{"name":"Remorhaz","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"magical beast","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":20,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+1 Dex, +11 natural, -2 size","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":7,"will":4,"immunities":["fire","cold"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":20}],"melee":"bite +13 (3d6+9 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"heat"},{"type":"swallow whole","details":"2d6+9 plus 8d6 fire, AC 15, hp 9"}],"strength":22,"dexterity":13,"constitution":21,"intelligence":5,"wisdom":12,"charisma":10,"baseatk":9,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":28,"cmd_special":"can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":16}],"languages":["Giant (cannot speak)"],"environments":["cold deserts","cold glaciers"],"organizations":["solitary"],"treasure":"none","description_visual":"An immense centipede-like beast erupts from the snow, rows of chitinous plates on its back glowing red-hot.","source":"PFRPG Bestiary","special_abilities":[{"type":"Heat","kind":"Su","details":"An enraged remorhaz generates heat so intense that anything touching its body takes 8d6 points of fire damage. Creatures striking a remorhaz with natural attacks or unarmed strikes are subject to this damage, but creatures striking with melee weapons are not. The heat can melt or burn weapons; any weapon that strikes a remorhaz is allowed a DC 19 Fortitude save to avoid taking damage. The save DC is Constitution-based."}],"description":"In a world of ice and snow, the remorhaz is particularly feared for the terrible fires that burn within its body. These internal fires cause the armor plates along its back to glow red-hot when the creature is particularly angry, excited, or in pain. Creatures adapted to arctic regions are often particularly vulnerable to fire, making the remorhaz's primary defense an incredibly potent one and securing its role as a dangerous predator in such frozen reaches.\n\nRemorhazes dwell in extensive warrens carved into the hearts of glaciers. The beasts use their heat to melt tunnels through ice, tunnels whose smooth glassy sides swiftly refreeze in their wake to create uncommonly stable and numerous mazes.\n\nAlthough the remorhaz has much in common superficially with lesser vermin, the beast is surprisingly intelligent. While not capable of speech, the typical remorhaz has a good grasp of the Giant tongue, and tribes of giants often use this to their advantage to secure allegiances with the great beasts. Frost giants are particularly obsessed with them, for those giants who brave the cruel and deadly burns a remorhaz can inf lict to become \"worm friends\" gain a potent weapon to use against their enemies-an assassin capable of burrowing up through the floor of a glacial keep to strike directly against a frost giant's greatest weakness: fire. Other giants use the beasts as living forges, for their backs are hot enough to melt metal.\n\nA remorhaz is 25 ft. long and weighs 10,000 pounds.","ecology":"","habitat_society":""},{"name":"Rot Grub Swarm","cr":7,"xp":3200,"alignment":"N","size":"Fine","type":"vermin","subtypes":["swarm"],"init":2,"senses":[{"type":"blindsense","modifier":"30 ft."}],"ac":20,"ac_touch":20,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 size","hp":85,"hd":"10d8+40","hdvalue":10,"fort":11,"ref":5,"will":3,"defensive_abilities":["swarm traits"],"immunities":["mind-affecting effects","weapon damage"],"speed":[{"type":"land","speed":10}],"melee":"swarm (2d6 plus distraction and infestation)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 19"},{"type":"infestation"}],"strength":1,"dexterity":15,"constitution":18,"wisdom":10,"charisma":1,"baseatk":7,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This nauseating carpet of wriggling white grubs undulates outward in a pallid wave of hunger.","group":"Parasite","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Infestation","kind":"Ex","details":"Any living creature that takes damage from a rot grub swarm becomes infested unless it succeeds at a DC 19 Reflex save. On a failed save, the infested creature takes 1d4 points of Constitution damage per round as the rot grubs burrow through and consume its flesh-this effect continues as long as the victim remains in the swarm and continues for 1d6 rounds after it leaves the swarm. Any energy-based attack (including damage from negative energy) that deals at least 5 points of damage to the victim automatically destroys all of the rot grubs infesting it, ending the effect prematurely. Additionally, any effect that removes disease instantly ends a rot grub infestation. Immunity to disease offers no defense. The save DC is Constitution-based."}],"description":"Rot grubs are foul, nauseating parasites that feed on flesh and use corpses as nests in which to grow. While a rot grub can derive nourishment from dead flesh, its true hunger is for the flesh of the living. Thankfully, rot grub swarms occur only rarely, as they require the infested carcass of a Huge or larger creature and many weeks to build up the numbers necessary to constitute a swarm.\n\nIn some cases, a rot grub continues to feed and grow, eventually reaching enormous size as a giant rot grub.","ecology":"","habitat_society":""},{"name":"Salikotal","cr":7,"xp":3200,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":17,"ac_flat_footed":16,"ac_mods":"+6 Dex, +1 dodge, +6 natural","hp":76,"hd":"9d10+27","hdvalue":9,"fort":9,"ref":12,"will":7,"dr":"5/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":18,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"+1 dagger +14 (1d4+5/17-20), tail +8 (1d4+2) or 2 claws +13 (1d4+4), tail +8 (1d4+2)","ranged":"+1 dagger +16 (1d4+5/17-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"contract killer"},{"type":"sneak attack","details":"+3d6"},{"type":"suicide"},{"type":"vengeance"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"spider climb"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"knock"},{"spell":"locate creature"}]},{"frequency":"1/day","spells":[{"spell":"mislead"},{"spell":"passwall"},{"spell":"statue","details":"self only"},{"spell":"summon devil","details":"level 3, 4 imps, 35%"}]},{"frequency":"3/day","spells":[{"spell":"blur","details":"self only"},{"spell":"darkness"},{"spell":"dimension door"},{"spell":"dispel magic"},{"spell":"silence"},{"spell":"suggestion"}]}],"strength":18,"dexterity":22,"constitution":17,"intelligence":15,"wisdom":19,"charisma":18,"baseatk":9,"cmb":13,"cmd":30,"feats":[{"feat":"Dodge"},{"feat":"Improved Critical (dagger)"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Wind Stance"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Disable Device","value":18},{"skill":"Disguise","value":16},{"skill":"Escape Artist","value":18},{"skill":"Knowledge (local)","value":11},{"skill":"Sense Motive","value":16},{"skill":"Sleight of Hand","value":18},{"skill":"Stealth","value":18}],"languages":["Celestial","Common","Infernal","telepathy 100 ft. Gear +1 dagger"],"environments":["any (Hell)"],"organizations":["solitary","team (2-8)"],"treasure":"standard (+1 dagger)","description_visual":"On lean limbs the color of spilt blood creeps a being of sinister grace. Eyes like embers and a sneer full of needle-thin teeth gleam from an unmistakably fiendish visage. A pair of crimson wings sprout from the back of the hairless humanoid form, fluttering silently like an assassin's cloak, while in one hand it clutches the twisted, dagger-like horn of some infernal terror.","group":"Devil","source":"AP 26","special_abilities":[{"type":"Contract Killer","kind":"Su","details":"A salikotal gains a +2 bonus on attack and damage rolls when attacking a specific individual it has marked for death. At the beginning of each day, it determines an individual to serve as its target and which one of its three vengeances it may make use of that day. It may not change this target or ability until the next day. The target may be any specific creature the salikotal knows of, even if it has not seen its target before. This target is treated as being known to a salikotal for the purposes of using its locate creature ability, even if the devil has never seen its victim before."},{"type":"Sneak Attack","kind":"Ex","details":"Anytime a salikotal's opponent is denied his Dexterity bonus to AC, or if a salikotal flanks his opponent, he deals an extra 3d6 points of damage. This ability is just like the rogue's sneak attack and subject to the same limitations."},{"type":"Suicide","kind":"Su","details":"As a standard action, a salikotal may target itself with a coup de grace attack. If the salikotal reduces itself to fewer than 0 hit points-or fails to do so but still fails the associated Fortitude save (DC = 10 + damage dealt)-the salikotal erupts in a burst of destructive energy. Any creature within 15 ft. of a salikotal that commits suicide is damaged by a blast of metal shards and needle-like scales, taking 6d6 points of damage (DC 17, save for half). The save DC is Constitution-based. Upon using this ability, a salikotal is permanently destroyed. This effect only takes place if a salikotal willingly ends its own life, not if it is killed by outside effects."},{"type":"Vengeance","kind":"Su","details":"While seeking a victim a salikotal prepares itself daily, honing its will to effectively slaughter its intended quarry. On a given day, chosen as part of its contract killer ability, a salikotal may gain the benefit of any one of the following powers, either the one it feels will most aid it or whichever one its summoner requests. Only one of these abilities is active on a given day, and it only comes into effect when a salikotal kills its intended target with a coup de grace. These executions only function on living creatures. Fideicide: The victim's soul is immediately shunted to a infernal prison on Erebus, the third layer of Hell. The soul can be returned to life, but upon casting the spell, the spellcaster attempting the resurrection takes an amount of fire damage equal to 1d6 x the victim's number of Hit Dice, and must make an immediate concentration check (DC 10 + damage delt + spell level) or lose the spell. Necrocide: After 1d4 rounds, the victim's body animates as a zombie under the salikotal's control. The devil may permanently grant control of the zombie to any sentient creature as a free action. Omnicide: The victim's body is utterly destroyed, disintegrating without a trace. Its clothing and possessions remain unharmed. Only spells that don't require a portion of the corpse may return the victim to life."}],"description":"Prince-killers and assassins of souls, salikotals serve as the bloody chisels by which the lords of Hell subtly shape the mortal world to their whims. Soaring through the night on silent wings, these murderous devils care nothing for life or reason, knowing only a single, murderous goal. Cloaked by shadow and silence, few ever glimpse the sharp features of a salikotal, for Hell's death-dealers reveal themselves only amid the haze of fading life. Lean, deft hunters, salikotals move like terrible predatory birds, each taloned step measured, cautious, and full of deadly intent. Protected by an armor of sharp, thin scales, these agile devils universally stand 5 ft., 4 inches tall, and weigh 85 pounds, their barbed frames supporting the breadth of their 8-foot-wide, bat-like wings. They have full control over their slender tails, nimbly manipulating objects and even wielding deadly, Hell-forged blades in these dexterous, prehensile appendages. Ecology Salikotals rise from the tenebrous reaches of Erebus's vaulted heights. Unblinking and endlessly patient, salikotals haunt the claustrophobic upper realms of the lightless labyrinth, stealthy and watchful but caring little for the doings of intruders or their lesser kin. Only the summons of conjurers or the diabolical elite rouse them from their eerie aerial stalkings, drawing them forth from the shadows for a chance to hone their death-dealing expertise in the name of Hell. Naturally silent, salikotals never vocalize even the slightest sound, relying on their innate telepathic abilities for communication. Even when using such mental interaction, though, the devils prove terse and resistant to conversation. For most summoners, a salikotal's only communication is a slow nod acknowledging its orders, and a nod in answer to the question of its murderous success. Habitat & Society Salikotals have little to do with others of their kind, be they other salikotals or other lesser devils in general. Emotionless and rigid even beyond the typical disciplines of Hell, these assassins realize they exist for but a single reason: to sow death. Their cold precision only wavers when they discuss payment for their most notorious murderous methods, wherein they demand specific types of gemstones in compensation for their grisly work. Few non-devils dare to suppose why salikotals request such precise payments, refusing to work for any other recompense, but among the damned spread rumors of vast vaults filled with glistening jewels, each a fabulous treasure and a representation of a life cut short by the blades of Hell. Summoning Salikotals As in all things, salikotals prove emotionless when it comes to being summoned. They have little reason to purposefully resist or accept a diabolist's call, unless ordered to do so by their infernal masters. Once a salikotal is summoned, though, only murder interests it. Any Charisma check made as part of the spell planar binding to convince a salikotal to undertake a mission other than assassination takes a -2 penalty. Once a salikotal has agreed to perform a murder for its summoner, it explains the signature vengeances its kind can inflict upon a victim and offers to exact one upon its summoner's victim for an associated price. The devil requests 1,000 gp for every Hit Die its target possesses (intrinsically gauging its victim's prowess), to be paid entirely in one of three types of gemstones: ruby for fideicide, onyx for necrocide, and jacyinth for omnicide. Salikotals prove exceedingly particular in these payments, and if a summoner cannot pay the price in the type of gem requested, the devil refuses to exact one of its vengeances. If the summoner tries to force a salikotal to use one of its vengeances, the devil takes offense and all of the summoner's Charisma-related interactions with it in the future take a -2 penalty.","ecology":"Salikotals rise from the tenebrous reaches of Erebus's vaulted heights. Unblinking and endlessly patient, salikotals haunt the claustrophobic upper realms of the lightless labyrinth, stealthy and watchful but caring little for the doings of intruders or their lesser kin. Only the summons of conjurers or the diabolical elite rouse them from their eerie aerial stalkings, drawing them forth from the shadows for a chance to hone their death-dealing expertise in the name of Hell. Naturally silent, salikotals never vocalize even the slightest sound, relying on their innate telepathic abilities for communication. Even when using such mental interaction, though, the devils prove terse and resistant to conversation. For most summoners, a salikotal's only communication is a slow nod acknowledging its orders, and a nod in answer to the question of its murderous success.","habitat_society":"Salikotals have little to do with others of their kind, be they other salikotals or other lesser devils in general. Emotionless and rigid even beyond the typical disciplines of Hell, these assassins realize they exist for but a single reason: to sow death. Their cold precision only wavers when they discuss payment for their most notorious murderous methods, wherein they demand specific types of gemstones in compensation for their grisly work. Few non-devils dare to suppose why salikotals request such precise payments, refusing to work for any other recompense, but among the damned spread rumors of vast vaults filled with glistening jewels, each a fabulous treasure and a representation of a life cut short by the blades of Hell. Summoning Salikotals As in all things, salikotals prove emotionless when it comes to being summoned. They have little reason to purposefully resist or accept a diabolist's call, unless ordered to do so by their infernal masters. Once a salikotal is summoned, though, only murder interests it. Any Charisma check made as part of the spell planar binding to convince a salikotal to undertake a mission other than assassination takes a -2 penalty. Once a salikotal has agreed to perform a murder for its summoner, it explains the signature vengeances its kind can inflict upon a victim and offers to exact one upon its summoner's victim for an associated price. The devil requests 1,000 gp for every Hit Die its target possesses (intrinsically gauging its victim's prowess), to be paid entirely in one of three types of gemstones: ruby for fideicide, onyx for necrocide, and jacyinth for omnicide. Salikotals prove exceedingly particular in these payments, and if a summoner cannot pay the price in the type of gem requested, the devil refuses to exact one of its vengeances. If the summoner tries to force a salikotal to use one of its vengeances, the devil takes offense and all of the summoner's Charisma-related interactions with it in the future take a -2 penalty."},{"name":"Sangoi","cr":7,"xp":3200,"alignment":"NE","size":"Small","type":"fey","init":9,"senses":[{"type":"hear heartbeat"},{"type":"low-light vision"}],"ac":20,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+5 Dex, +1 dodge, +3 natural, +1 size","hp":71,"hd":"11d6+33","hdvalue":11,"fort":6,"ref":12,"will":8,"dr":"5/silver","speed":[{"type":"land","speed":30}],"melee":"dagger +11 (1d3+1/19-20), bite +11 (1d4+1 plus 1d4 bleed) or   bite +11 (1d4+1 plus 1d4 bleed), 2 claws +11 (1d3+1 plus 1d4 bleed)","ranged":"dagger +11 (1d3+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood rage"},{"type":"curse of misery"},{"type":"horrific critical"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"hide from animals","details":"self only"},{"spell":"hide from undead","details":"self only"}]},{"frequency":"at-will","spells":[{"spell":"detect thoughts"},{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"control weather"},{"spell":"dominate animal"},{"spell":"speak with dead"}]},{"frequency":"3/day","spells":[{"spell":"animal trance"},{"spell":"invisibility","details":"self only"},{"spell":"snare"}]}],"strength":13,"dexterity":21,"constitution":16,"intelligence":14,"wisdom":12,"charisma":19,"baseatk":5,"cmb":5,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Bluff","value":18},{"skill":"Craft (traps)","value":10},{"skill":"Diplomacy","value":10},{"skill":"Disguise","value":18},{"skill":"Escape Artist","value":10},{"skill":"Intimidate","value":15},{"skill":"Knowledge (local)","value":10},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":15},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":23}],"languages":["Aklo","Common","Sylvan","tongues"],"sq":[{"type":"change shape","details":"Medium or Small land animal or humanoid"},{"type":"sideways glance"},{"type":"sunlight transparency"}],"environments":["any cold land","any temperate land"],"organizations":["solitary","pair"],"treasure":"standard (dagger)","description_visual":"Dressed in tattered finery, this small, bald humanoid has a gaunt and haggard face with sallow skin drawn tight against its delicate bones. Its fingers and nails are unnaturally long and spidery, its teeth needle-sharp, and its body so thin it seems it could almost disappear if it turned sideways.","source":"AP 69","special_abilities":[{"type":"Curse of Misery","kind":"Su","details":"As a full-round action, a sangoi can deliver its curse to an adjacent humanoid as a melee touch attack. If the target fails its saving throw, the sangoi gains the benefit of aid (caster level equal to the target's Hit Dice). In addition, a sangoi gains a +2 morale bonus on attack rolls, weapon damage rolls, saving throws, and opposed skill checks against any creature affected by its curse of misery. A creature that successfully saves can not be affected by the same sangoi's curse for 24 hours. The save DC is Charisma-based. Curse of Misery: Touch-contact; save Will DC 19; frequency 1 day; effect permanent crushing despair."},{"type":"Hear Heartbeat","kind":"Ex","details":"A sangoi can hear the beating hearts of living creatures nearby, granting it blindsense 30 ft. and blindsight 5 ft.; it can locate all creatures taking bleed damage within 30 ft. as if it had blindsight. This ability doesn't reveal the location of creatures without hearts, including elementals, oozes, plants, undead, and incorporeal creatures."},{"type":"Horrific Critical","kind":"Ex","details":"When a sangoi enters a blood rage, its claws and teeth elongate and sharpen, threatening a critical hit on a roll of 18-20 (in addition to the other benefits of blood rage). If a sangoi reduces a humanoid to -1 or fewer hit points with a critical hit from one of its natural weapons, it can tear out the target's heart and consume it as a free action (Fortitude DC 19 negates), killing it instantly. If successful, the sangoi gains 1d8 temporary hit points and a +2 enhancement bonus to Strength. Any humanoid within 30 ft. who witnesses this attack must succeed at a DC 19 Will save or become shaken and sickened for 1d4 rounds (this is a mind-affecting fear effect). The save DCs are Charisma-based."},{"type":"Sideways Glance","kind":"Su","details":"Sangois fade from view when in a creature's peripheral vision. They automatically gain concealment against creatures that they flank with another creature (another sangoi or otherwise). They can also attempt a Bluff check to feint in combat as a swift action, but only against a foe that can clearly see them."},{"type":"Sunlight Transparency","kind":"Ex","details":"Direct sunlight causes a sangoi to partially fade from view. Their bodies become almost transparent (20% miss chance), and they become fatigued and take a -10 penalty on Disguise checks as long as they remain in direct sunlight."}],"description":"Sangois are malevolent nocturnal fey that haunt small towns and graveyards. Because of their taste for blood and their similar habits, they are sometimes mistaken for vampires. Sangoi appear as short, emaciated humanoids seldom over 4 ft. tall and weighing 35 to 40 pounds.\n\nEcology\n\nSangois thirst for the blood of the living, preferring humanoid blood, but settling for animal blood when humanoids are in short supply or when they are operating in disguise and don't wish to reveal their presence with an open attack. Though it is much harder to acquire, they are especially fond of the blood of good-aligned magical beasts, unicorns in particular. While blood provides physical nourishment for them, they also draw psychic sustenance from inf licting anguish and despair.\n\nSangois are expert trappers, catching large and small animals with magic or mundane snares. Trapped beasts might be mutilated for a sangoi's pleasure, though the wicked fey more likely dominates them and uses them to commit murder and mischief.\n\nHabitat & Society\n\nSangois are natives of the fey realms of the First World, but they spend little time there. Most of their time is spent roaming the Material Plane, lurking in shadows and places where death and sorrow linger, such as graveyards and ruins. They are wanderers, moving from village to village in search of their next victims. When a target is located, a sangoi (or, rarely, a pair of sangois working together) seeks to isolate the victim in order to murder it and take its form. The sangoi poses as its victim, while draining the emotional, mental, and physical energy out of those that give them succor with its curse of misery.\n\nSangoi consider themselves hunters of a sort, seeking children born with certain unique characteristics or deformities, such as those born covered with a caul, or who bear a particular birthmark or hair or eye color. Sangois fear those with such marks, whatever they might be, believing they render them powerless against such creatures and that if those with the marks are able to grow to maturity, they will bring ruin to the sangoi. Each individual sangoi has its own particular mark it grows to fear.\n\nChildren so marked are spirited away from their mortal parents and slain, sold as slaves to an evil fey master, or simply imprisoned in the depths of a sangoi's lair, all to quell whatever threat the sangois believe they pose.\n\nWhen such a child is found, a sangoi begins lurking about the home in the guise of an animal and might even take the form of a pet to attract the child's affection. Its curse falls upon the household with this infiltration, though sangois credit their chosen targets with immunity to their powers, or even the ability to block their powers from affecting others. Sangois attempt to abduct their targets at birth when possible, but often they don't discover them until a target is older. In such cases, sangois try to kill or kidnap their targets using dominated wild animals or traps set up to look like natural accidents.\n\nOnce a victim has been taken, a sangoi changes its shape to assume the victim's form, usually spending several days reading the victim's thoughts or speaking with its corpse to learn about it so it might better impersonate him. The sangoi then returns to the victim's home and assumes its life, going about his daily business while keeping out of direct sunlight when possible, often feigning illness or injury.\n\nOnce the sangoi enters its victim's home, its curse of misery begins to take hold, sapping the life and spirit from the family and friends of its victim. The sangoi amuses itself with the abuse and murder of domestic animals through traps and magical compulsion, and calls foul weather to cast a pall upon the house while it waits for the family of its victim to slip into ennui. Once those in the house fall into utter despair, the sangoi plans elaborate murders in which it renders its targets helpless, often with traps using common household objects and implements, and then carves out and greedily devours the hearts of its helpless victims, savoring the sour tang of fear that lingers in broken hearts even after death.","ecology":"Sangois thirst for the blood of the living, preferring humanoid blood, but settling for animal blood when humanoids are in short supply or when they are operating in disguise and don't wish to reveal their presence with an open attack. Though it is much harder to acquire, they are especially fond of the blood of good-aligned magical beasts, unicorns in particular. While blood provides physical nourishment for them, they also draw psychic sustenance from inf licting anguish and despair.\n\nSangois are expert trappers, catching large and small animals with magic or mundane snares. Trapped beasts might be mutilated for a sangoi's pleasure, though the wicked fey more likely dominates them and uses them to commit murder and mischief.","habitat_society":"Sangois are natives of the fey realms of the First World, but they spend little time there. Most of their time is spent roaming the Material Plane, lurking in shadows and places where death and sorrow linger, such as graveyards and ruins. They are wanderers, moving from village to village in search of their next victims. When a target is located, a sangoi (or, rarely, a pair of sangois working together) seeks to isolate the victim in order to murder it and take its form. The sangoi poses as its victim, while draining the emotional, mental, and physical energy out of those that give them succor with its curse of misery.\n\nSangoi consider themselves hunters of a sort, seeking children born with certain unique characteristics or deformities, such as those born covered with a caul, or who bear a particular birthmark or hair or eye color. Sangois fear those with such marks, whatever they might be, believing they render them powerless against such creatures and that if those with the marks are able to grow to maturity, they will bring ruin to the sangoi. Each individual sangoi has its own particular mark it grows to fear.\n\nChildren so marked are spirited away from their mortal parents and slain, sold as slaves to an evil fey master, or simply imprisoned in the depths of a sangoi's lair, all to quell whatever threat the sangois believe they pose.\n\nWhen such a child is found, a sangoi begins lurking about the home in the guise of an animal and might even take the form of a pet to attract the child's affection. Its curse falls upon the household with this infiltration, though sangois credit their chosen targets with immunity to their powers, or even the ability to block their powers from affecting others. Sangois attempt to abduct their targets at birth when possible, but often they don't discover them until a target is older. In such cases, sangois try to kill or kidnap their targets using dominated wild animals or traps set up to look like natural accidents.\n\nOnce a victim has been taken, a sangoi changes its shape to assume the victim's form, usually spending several days reading the victim's thoughts or speaking with its corpse to learn about it so it might better impersonate him. The sangoi then returns to the victim's home and assumes its life, going about his daily business while keeping out of direct sunlight when possible, often feigning illness or injury.\n\nOnce the sangoi enters its victim's home, its curse of misery begins to take hold, sapping the life and spirit from the family and friends of its victim. The sangoi amuses itself with the abuse and murder of domestic animals through traps and magical compulsion, and calls foul weather to cast a pall upon the house while it waits for the family of its victim to slip into ennui. Once those in the house fall into utter despair, the sangoi plans elaborate murders in which it renders its targets helpless, often with traps using common household objects and implements, and then carves out and greedily devours the hearts of its helpless victims, savoring the sour tang of fear that lingers in broken hearts even after death."},{"name":"Sceaduinar","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"lifesense"},{"type":"low-light vision"}],"ac":20,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+5 Dex, +1 dodge, +4 natural","hp":85,"hd":"9d10+36","hdvalue":9,"fort":10,"ref":11,"will":5,"defensive_abilities":["entropic flesh","negative energy affinity","void child"],"dr":"10/adamantine or good","immunities":["cold","death effects","disease","energy drain","poison"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"sonic","value":10}],"sr":18,"speed":[{"type":"land","speed":40},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"bite +14 (1d6+3 plus 1d6 negative energy and energy drain), 2 wings +9 (1d6+1 plus 1d6 negative energy)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"energy drain","details":"1 level, DC 17"},{"type":"entropic touch"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"entropic shield"},{"spell":"hide from undead"}]},{"frequency":"at-will","spells":[{"spell":"bleed"},{"spell":"dimension door","details":"self only"},{"spell":"dispel magic"}]},{"frequency":"1/day","spells":[{"spell":"antilife shell"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"harm"},{"spell":"slay living"}]},{"frequency":"3/day","spells":[{"spell":"death knell"},{"spell":"deeper darkness"},{"spell":"enervation"},{"spell":"inflict serious wounds"},{"spell":"silence"}]}],"strength":17,"dexterity":20,"constitution":18,"intelligence":13,"wisdom":14,"charisma":17,"baseatk":9,"cmb":12,"cmd":28,"feats":[{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Skill Focus (Perception)"},{"feat":"Step Up"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Escape Artist","value":17},{"skill":"Fly","value":9},{"skill":"Intimidate","value":15},{"skill":"Knowledge (nature)","value":13},{"skill":"Knowledge (planes)","value":17},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":25}],"languages":["Aklo","Common"],"environments":["any (Negative Energy Plane)"],"organizations":["solitary","death squad (2-11)"],"treasure":"standard","description_visual":"This gargoyle-like creature has long spiky legs and a bat-like head-its body seems to be made of living, dark purple crystal.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Entropic Flesh","kind":"Ex","details":"Any creature that hits a sceaduinar with a melee attack takes 1d6 points of negative energy damage. Attacking with a weapon that provides reach allows a creature to avoid taking this damage."},{"type":"Entropic Touch","kind":"Ex","details":"A sceaduinar's natural attacks can strike incorporeal creatures as if they were ghost touch weapons. All of a sceaduinar's natural attacks deal +1d6 points of negative energy damage to the target. This energy doesn't heal creatures healed by inflict spells."},{"type":"Void Child","kind":"Ex","details":"Sceaduinars are immune to effects that target souls (such as trap the soul) or require knowledge of a creature's identity (such as scrying). When one is slain, it cannot be restored to life by magic save by a miracle or wish, or by divine intervention."}],"description":"Sceaduinars are strange creatures born of pure entropy, the antithesis of creation and life. In the cold heart of the Negative Energy Plane, the un-substance of that realm coalesces into snowf lake-like crystals, and it is from these strange formations that sceaduinars arise, breaking free from their jagged \"eggs\" fully grown. They hate the living and the undead with equal passion, perhaps out of jealousy for those who have a spark of life (even if that spark is provided by a corruption of life in the form of undeath), though they usually ignore creatures from the Outer Sphere. They believe their positive energy counterparts, the jyoti, long ago stole their ability to create, breaking the parallel between the two energy planes and forcing these void-dwellers into an unwanted role of pure destruction.\n\nIn a way, their hatred parallels that of another native of the Negative Energy Plane-the nightshade. Yet despite their similar goals, the sceaduinars see nightshades as just another corruption of life worthy of destruction- even though very few sceaduinars are powerful enough to directly oppose one of these deadly undead. Sceaduinars are quite intelligent, yet they have no real society to speak of. When they gather together, it is always to form a larger band to strike against a particularly dangerous foe.","ecology":"","habitat_society":""},{"name":"Serpopard","cr":7,"xp":3200,"alignment":"CN","size":"Medium","type":"magical beast","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+5 Dex, +5 natural","hp":85,"hd":"9d10+36","hdvalue":9,"fort":10,"ref":11,"will":7,"speed":[{"type":"land","speed":40}],"melee":"bite +14 (1d6+4/19-20), 2 claws +14 (1d4+4 plus grab)","space":"5 ft.","reach":"5 ft. (15 ft. with bite)","special_attacks":[{"type":"dune step"},{"type":"limber neck"},{"type":"pounce"},{"type":"rake","details":"bite +14, 1d6+4; 2 claws +14, 1d4+4"}],"strength":19,"dexterity":21,"constitution":18,"intelligence":10,"wisdom":14,"charisma":17,"baseatk":9,"cmb":13,"cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+14 when jumping"},{"skill":"Bluff","value":9},{"skill":"Climb","value":8},{"skill":"Knowledge (geography)","value":5},{"skill":"Perception","value":10},{"skill":"Stealth","value":15},{"skill":"Survival","value":8}],"languages":["Common"],"sq":[{"type":"far wanderer"}],"environments":["warm deserts","warm plains"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"The muscles beneath the spotted fur of this sleek feline tense, poised to pounce. Its long, sinuous neck stretches over twice the length of its body, ending in a snarling leopard's head.","source":"AP 81","special_abilities":[{"type":"Dune Step","kind":"Su","details":"Three times per day as part of a move action, a serpopard can instantaneously leap from one dune to any other dune within 1 mile as if by dimension door. The serpopard must begin and end this movement in an area of dunes. Using this ability doesn't provoke attacks of opportunity."},{"type":"Far Wanderer","kind":"Ex","details":"Knowledge (geography) and Survival are class skills for serpopards."},{"type":"Limber Neck","kind":"Ex","details":"A serpopard can use its long neck to make bite attacks as part of a rake attack against grappled opponents. In addition, a serpopard doesn't take the usual -2 penalty on attack rolls when it makes a bite attack while grappling."}],"description":"Avistani naturalists named this creature serpopard because they saw it as possessing features of both a leopard and a serpent, though this creature is also widely known by its Osiriani name sedja, meaning \"one who travels from afar.\" Serpopards earn this appellation because of their supernatural ability to leap from one dune to another, an ability they call \"stepping between the dunes.\"\n\nSome scholars speculate that the pharaohs of old bred this ability into the serpopards in order to create scouts and messengers able to cross the harsh terrain of their vast empires quickly and efficiently, but this creature isn't one that has been created or inf luenced by humankind. Though rare, serpopards are naturally occurring beasts native to the deserts of northern Garund. Superstitious folk who believe that the gods' hands touch everything beneath the blistering Osirian sun see the serpopard as a cursed creature, marked with snakelike features by Apep and forced to wander eternally through the desert, never to find rest or sanctuary. On the other hand, carvings on ceremonial plates, on uncovered artifacts, and in ruined temples make it clear that the god-kings of Ancient Osirion once kept serpopards as pets or servants, as depictions of these creatures in the oldest of Osirion's ruins often show them chained or collared, bowing obediently to human masters.\n\nSerpopards stand approximately 3 ft. tall at the shoulder; when their necks are fully extended, they can measure up to 20 ft. long from nose to tail. Serpopards weigh anywhere from 150 to 200 lbs.\n\nEcology\n\nThough serpopards are most common in the deserts of northern Garund, travelers in such far-off locales as the Meraz Desert in Qadira, the Cinderlands of Varisia, and the vast expanse of Shaguang in Tian Xia to the east have spotted creatures matching the serpopards' description. Some sages hypothesize that the most powerful or ancient serpopards can cross greater distances with their dune step ability, and thus travel through it to distant deserts across Golarion. Such experts say it's therefore likely that all deserts hold populations of serpopards, though they may be few in number or very isolated.\n\nSerpopards are largely nocturnal, preferring to hunt at night when they can use the cover of darkness to approach prey undetected. When hunting, they rely on their speed and powerful claws to take down large quarry, and then use the additional reach provided by their unusually long necks to defend their kills from scavengers and competing hunters. Serpopards are not averse to eating intelligent beings, and hunt humanoids if the opportunity or need arises, but they aren't cruel- serpopards gain no pleasure from such acts beyond the satisfaction of a fresh meal.\n\nOn average, serpopards have a lifespan of about 50 years, but rumors exist of serpopards living much longer than this. One town along the northern coast of Rahadoum claims a single serpopard has visited its outskirts once every decade for the past 100 years.\n\nHabitat & Society\n\nSerpopards are mainly solitary creatures. Very rarely do they travel in pairs, and then only during mating season or in the case of littermates who chose not to separate at adulthood. When living as mated pairs, the father stays only until the cubs are able to run, but the mother stays with the cubs much longer, teaching them how to hunt and use their special ability to travel between the dunes. Mothers also pass on to the cubs their understanding of the land, instructing them as to which areas are good for hunting or exploring, what kinds of places to avoid, and how to find fresh water. Young serpopards separate from their mother individually, leaving as soon as they mature and feel confident navigating their way through the desert alone.\n\nWhen traveling, serpopards range anywhere from 50 to 100 miles per day, stopping only to hunt, rest, or (more rarely) explore some aged ruin. No one knows what fascination these ancient works hold for the serpopards, but the creatures' interest in such locations is undeniable. An old poem involving serpopards claims that the creatures visit these ancient ruins because they are pining for the lost empire of Ancient Osirion.\n\nSerpopards are clever liars and frustrating conversationalists, and hold a reputation among other races as skilled deceivers. In rural parts of Osirion, those with a gift for deception are often said to have \"the tongue of a sedja,\" while young children caught in a lie are warned that their \"necks are growing\" with each lie they tell. Despite this potential untrustworthiness, many people still seek the aid of serpopards. Few creatures know the deserts of Osirion as well as serpopards, and for the right price many are willing to guide groups of people across the desert. It's usually best to ensure the serpopard is well fed before undertaking such a journey, however, for a hungry serpopard may turn on its traveling companions if it thinks it can make a quick meal out of them. Serpopards have little use for gold and rarely accept it as payment for their services, though some apparently take a liking to jewelry, as travelers report the creatures as frequently wearing necklaces and bracelets when encountered. Food and hospitality are always acceptable payments, for those two things are in short supply in the harsh expanse of the desert. For those wishing to earn a serpopard's true faith and loyalty, however, one form of compensation stands above all others-divination magic. Serpopards are unceasingly curious about what their futures hold, and put great stock in the words of those who can tell fortunes or predict events to come.\n\nSerpopards attack most sphinxes on sight, often fighting at least long enough to get in a few solid blows before retreating between the dunes to safety. The only exception to this is androsphinxes, which most serpopards fear for some unknown reason. Only the bravest or most desperate serpopards face down such creatures in combat without aid; most flee immediately once they spot these mighty sphinxes. Sphinxes are aware of this antipathy and treat serpopards accordingly. Perhaps as a consequence of their antipathy toward sphinxes, serpopards also hate riddles and word games, and prefer to twist their words with lies and omissions rather than making a game out of conversation. Ignorant travelers who confuse the two creatures and try to engage the serpopard in a bout of riddling can find themselves in a dangerous predicament.","ecology":"Though serpopards are most common in the deserts of northern Garund, travelers in such far-off locales as the Meraz Desert in Qadira, the Cinderlands of Varisia, and the vast expanse of Shaguang in Tian Xia to the east have spotted creatures matching the serpopards' description. Some sages hypothesize that the most powerful or ancient serpopards can cross greater distances with their dune step ability, and thus travel through it to distant deserts across Golarion. Such experts say it's therefore likely that all deserts hold populations of serpopards, though they may be few in number or very isolated.\n\nSerpopards are largely nocturnal, preferring to hunt at night when they can use the cover of darkness to approach prey undetected. When hunting, they rely on their speed and powerful claws to take down large quarry, and then use the additional reach provided by their unusually long necks to defend their kills from scavengers and competing hunters. Serpopards are not averse to eating intelligent beings, and hunt humanoids if the opportunity or need arises, but they aren't cruel- serpopards gain no pleasure from such acts beyond the satisfaction of a fresh meal.\n\nOn average, serpopards have a lifespan of about 50 years, but rumors exist of serpopards living much longer than this. One town along the northern coast of Rahadoum claims a single serpopard has visited its outskirts once every decade for the past 100 years.","habitat_society":"Serpopards are mainly solitary creatures. Very rarely do they travel in pairs, and then only during mating season or in the case of littermates who chose not to separate at adulthood. When living as mated pairs, the father stays only until the cubs are able to run, but the mother stays with the cubs much longer, teaching them how to hunt and use their special ability to travel between the dunes. Mothers also pass on to the cubs their understanding of the land, instructing them as to which areas are good for hunting or exploring, what kinds of places to avoid, and how to find fresh water. Young serpopards separate from their mother individually, leaving as soon as they mature and feel confident navigating their way through the desert alone.\n\nWhen traveling, serpopards range anywhere from 50 to 100 miles per day, stopping only to hunt, rest, or (more rarely) explore some aged ruin. No one knows what fascination these ancient works hold for the serpopards, but the creatures' interest in such locations is undeniable. An old poem involving serpopards claims that the creatures visit these ancient ruins because they are pining for the lost empire of Ancient Osirion.\n\nSerpopards are clever liars and frustrating conversationalists, and hold a reputation among other races as skilled deceivers. In rural parts of Osirion, those with a gift for deception are often said to have \"the tongue of a sedja,\" while young children caught in a lie are warned that their \"necks are growing\" with each lie they tell. Despite this potential untrustworthiness, many people still seek the aid of serpopards. Few creatures know the deserts of Osirion as well as serpopards, and for the right price many are willing to guide groups of people across the desert. It's usually best to ensure the serpopard is well fed before undertaking such a journey, however, for a hungry serpopard may turn on its traveling companions if it thinks it can make a quick meal out of them. Serpopards have little use for gold and rarely accept it as payment for their services, though some apparently take a liking to jewelry, as travelers report the creatures as frequently wearing necklaces and bracelets when encountered. Food and hospitality are always acceptable payments, for those two things are in short supply in the harsh expanse of the desert. For those wishing to earn a serpopard's true faith and loyalty, however, one form of compensation stands above all others-divination magic. Serpopards are unceasingly curious about what their futures hold, and put great stock in the words of those who can tell fortunes or predict events to come.\n\nSerpopards attack most sphinxes on sight, often fighting at least long enough to get in a few solid blows before retreating between the dunes to safety. The only exception to this is androsphinxes, which most serpopards fear for some unknown reason. Only the bravest or most desperate serpopards face down such creatures in combat without aid; most flee immediately once they spot these mighty sphinxes. Sphinxes are aware of this antipathy and treat serpopards accordingly. Perhaps as a consequence of their antipathy toward sphinxes, serpopards also hate riddles and word games, and prefer to twist their words with lies and omissions rather than making a game out of conversation. Ignorant travelers who confuse the two creatures and try to engage the serpopard in a bout of riddling can find themselves in a dangerous predicament."}];
